from hypothesis import strategies as st

@st.composite
def gen(draw):
    t = draw(st.integers(1, 4))
    parts = [str(t)]
    for _ in range(t):
        n = draw(st.integers(1, 6))
        # small values, with duplicates and the special pair {1,2} likely
        a = draw(st.lists(st.integers(1, 6), min_size=n, max_size=n))
        parts.append(str(n))
        parts.append(" ".join(map(str, a)))
    return "\n".join(parts) + "\n"

def validate(inp):
    tok = inp.split()
    if not tok:
        return False
    pos = 0
    try:
        t = int(tok[pos]); pos += 1
        if not (1 <= t <= 10**4):
            return False
        total = 0
        for _ in range(t):
            if pos >= len(tok):
                return False
            n = int(tok[pos]); pos += 1
            if not (1 <= n <= 2 * 10**5):
                return False
            total += n
            if pos + n > len(tok):
                return False
            a = [int(x) for x in tok[pos:pos + n]]
            pos += n
            if not all(1 <= x <= 10**9 for x in a):
                return False
        if total > 2 * 10**5:
            return False
        return pos == len(tok)
    except ValueError:
        return False

def ref(inp):
    tok = inp.split()
    pos = 0
    t = int(tok[pos]); pos += 1
    out = []
    for _ in range(t):
        n = int(tok[pos]); pos += 1
        a = [int(x) for x in tok[pos:pos + n]]
        pos += n
        cnt = 0
        for i in range(n):
            for j in range(i + 1, n):
                # b_i^{b_j} == b_j^{b_i} with b = 2^a, literal definition
                # (2^a_i)^(2^a_j) = 2^(a_i * 2^a_j)
                if a[i] * 2 ** a[j] == a[j] * 2 ** a[i]:
                    cnt += 1
        out.append(str(cnt))
    return "\n".join(out)
